Let $f: \mathbb{R}^d \to \mathbb{R}$ be differentiable. We use $\langle \cdot, \cdot \rangle$ for the inner product of $\mathbb R^d$.

The Bregman divergence of $f$ between $x, y \in \mathbb{R}^d$ is 
\begin{equation*}
D_f(y,x) := f(y) - f(x) - \langle \nabla f(x),\, y - x \rangle .
\end{equation*}
In general, $D_f$ is not symmetric, i.e., $D_f(y,x) \neq D_f(x,y)$.  
Its symmetrization, called the symmetrized Bregman divergence, is  
\begin{equation}\label{eq:symBre}
D_f(y,x) + D_f(x,y)
= \langle \nabla f(y) - \nabla f(x),\, y - x \rangle .
\end{equation}
Define the difference of Bregman divergences
\begin{equation*}
\Delta_f(x,y) := D_f(y,x) - D_f(x,y).
\end{equation*}
We can rewrite the symmetric Bregman divergence via the asymmetry:
\begin{equation}\label{eq:Brelation}
\langle \nabla f(x) - \nabla f(y),\, x - y \rangle 
= 2D_f(x,y) + \Delta_f(x,y).
\end{equation}

The following three-point Bregman identity holds~\cite{chen1993convergence}:
\begin{equation}\label{eq:Bregmanidentity}
\langle \nabla f(y) - \nabla f(x),\, y - z \rangle 
= D_f(y,x) + D_f(z,y) - D_f(z,x),
\end{equation}
which is a generalization of the classical identity of squares:
\begin{equation}\label{eq:squares}
\langle y-x,\, y-z \rangle
=
\frac12\bigl(
\|y-x\|^2 + \|z-y\|^2 - \|z-x\|^2
\bigr).
\end{equation}

The function $f$ is $\mu$-strongly convex if for some $\mu > 0$,
\begin{equation*}
D_f(y,x) \geq \frac{\mu}{2} \|y - x\|^2, 
\qquad \forall x, y \in \mathbb{R}^d.
\end{equation*}
It is $L$-smooth, for some $L > 0$, if its gradient is $L$-Lipschitz:
\begin{equation*}
\|\nabla f(y) - \nabla f(x)\| \leq L \|y - x\|, 
\qquad \forall x, y \in \mathbb{R}^d.
\end{equation*}

Let $\mathcal{S}_{\mu,L}$ be the class of all differentiable functions that are both $\mu$-strongly convex and $L$-smooth.  
For $f \in \mathcal{S}_{\mu,L}$, the Bregman divergence satisfies~\cite{nesterov2003introductory}
\begin{equation}\label{eq:muLsquares}
\frac{\mu}{2} \| x - y \|^2 
\leq D_f(x,y) 
\leq \frac{L}{2} \| x - y \|^2, 
\qquad \forall x, y \in \mathbb{R}^d,
\end{equation}
and, in terms of gradient differences,
\begin{equation}\label{eq:cocov}
\frac{1}{2L} \|\nabla f(x) - \nabla f(y)\|^2 
\leq D_f(x,y) 
\leq \frac{1}{2\mu} \|\nabla f(x) - \nabla f(y)\|^2, 
\qquad \forall x, y \in \mathbb{R}^d.
\end{equation}

The continuous-time HNAG flow is
\begin{equation}\label{eq:flow}
\left\{
\begin{aligned}
x' &= y - x - \beta \nabla f(x), \\
y' &= x - y - \tfrac{1}{\mu}\nabla f(x),
\end{aligned}
\right.
\end{equation}

where $\mu$ is the strong convexity parameter of $f$.
Let $\boldsymbol z=(x,y)$ and define
\begin{equation}\label{eq:G}
\mathcal G(\boldsymbol z)
=\bigl(y-x-\beta\nabla f(x),\; x-y-\tfrac{1}{\mu}\nabla f(x)\bigr)^{\intercal},
\end{equation}

An implicit--explicit (IMEX) discretization of~\eqref{eq:flow} yields
\begin{subequations}\label{eq:HNAG}
\begin{align}
\label{eq:HNAGx}
\frac{x_{k+1}-x_k}{\alpha} &= y_k - x_{k+1} - \beta \nabla f(x_k), \\
\label{eq:HNAGy}
\frac{y_{k+1}-y_k}{\alpha} &= x_{k+1} - y_{k+1} - \tfrac{1}{\mu}\nabla f(x_{k+1}),
\end{align}

\begin{algorithm}
\caption{HNAG$^{++}$}
\label{alg:HNAGpp}
\linespread{1.3}\selectfont
\begin{algorithmic}[1]
\Require $x_0,v_0\in\mathbb R^d$, parameters $L\ge \mu>0$
\State $\alpha \gets \sqrt{2\mu/L}$
\For{$k=0,1,2,\ldots$}
\State $v_{k+1}\gets \tfrac{1}{1+\alpha}
\bigl(v_k+\alpha^2 x_k-\tfrac{2}{L}\nabla f(x_k)\bigr)$
\State $x_{k+1}\gets \tfrac{1}{1+\alpha}
\bigl(x_k+v_{k+1}-\tfrac{1}{L}\nabla f(x_k)\bigr)$
\EndFor
\State \textbf{Return:} $x_{k+1}$ and $y_{k} = v_{k+1}/\alpha$
\end{algorithmic}
\end{algorithm}

\begin{equation}\label{eq:lya-muhat}
\mathcal{E}(\bs z; \hat{\mu})
:= D_{f_{-\hat{\mu}}}(x, x^{\star})
+ \tfrac{\mu}{2}\|y - x^{\star}\|^2.
\end{equation}

If $f\in\mathcal S_{\mu,L}^{\rm LAS}(x^\star)$, then
\begin{equation}\label{eq:def-omegak}
\omega(\|x_{k+1}-x^\star\|)
\leq
\omega\left(
C_1\left(1+\sqrt{2\rho}\right)^{-\frac{k+1}{2}}
\right)
=:\omega_k.
\end{equation}

\begin{lemma}\label{lem:cont_strong}
Let $\mathcal G(\boldsymbol z)$ be the vector field of the HNAG flow~\eqref{eq:flow}.
Then $E(\boldsymbol z)$ satisfies the following strong Lyapunov condition
\begin{equation}\label{eq:A-HNAG}
-\langle\nabla E(\boldsymbol z),\mathcal G(\boldsymbol z)\rangle
\;\ge\;
E(\boldsymbol z)+\beta\|\nabla f(x)\|^2+\frac{\mu}{2}\|x-y\|^2 .
\end{equation}
\end{lemma}

\begin{lemma}\label{lem:disc_strong}
Let $(x_k,y_k)$ be the iterates generated by~\eqref{eq:HNAG} and $E$ defined by \eqref{eq:lyapunov_strong_HNAG}. Then
\begin{equation}\label{eq:onestep}
\begin{aligned}
(1+\alpha)E(\bs z_{k+1}) \;\le\;& E(\bs z_k)
+ \Bigl(\frac{\alpha^2}{2\mu}-\frac{\alpha\beta}{2}\Bigr)\|\nabla f(x_{k+1})\|^2
- \frac{\alpha\beta}{2}\|\nabla f(x_k)\|^2 \\
\qquad-\frac{\alpha \mu}{2}\|x_{k+1} - y_{k+1}\|^2 &+ \frac{\alpha\beta}{2}\|\nabla f(x_{k+1})-\nabla f(x_k)\|^2
- D_f(x_k,x_{k+1}).
\end{aligned}
\end{equation}
\end{lemma}

