\begin{proof}
Expand the difference of $E$ by the definition of the Bregman divergence:
\begin{equation*}
E(\bs z_{k+1})-E(\bs z_k)
= \langle \nabla E(\bs z_{k+1}),\,\bs z_{k+1}-\bs z_k\rangle
- D_E(\bs z_k,\bs z_{k+1}),
\end{equation*}
where
\begin{equation}\label{eq:DEHNAG}
- D_E(\bs z_k,\bs z_{k+1})
= -D_f(x_k,x_{k+1})-\frac{\mu}{2}\|y_k-y_{k+1}\|^2 .
\end{equation}

\textbf{The implicit Euler term.} We apply the strong Lyapunov property \eqref{eq:A-HNAG} at $\bs z_{k+1}$ to the implicit Euler term
\begin{equation*}
\langle \nabla E(\bs z_{k+1}),\,\alpha \mathcal G(\bs z_{k+1}) \rangle \leq - \alpha E(\boldsymbol z_{k+1}) - \alpha\beta\|\nabla f(x_{k+1})\|^2-\frac{\alpha \mu}{2}\|x_{k+1} - y_{k+1}\|^2.
\end{equation*}

\medskip
\noindent

\textbf{Lagging of \(y\).}
%
%This yields two cross terms in the Lyapunov difference:
%\begin{align*}
%\alpha\langle \nabla f(x_{k+1}),\,y_k-y_{k+1}\rangle\quad
%\mathrm{and}\quad \alpha\beta\langle \nabla f(x_{k+1}),\,\nabla f(x_{k+1})-\nabla f(x_k)\rangle .
%\end{align*}
For the term $\alpha\langle \nabla f(x_{k+1}),\,y_k-y_{k+1}\rangle$ arising from the lagging of $y$, the Cauchy--Schwarz and Young inequalities give
\begin{equation}\label{eq:firstcross}
\alpha\langle \nabla f(x_{k+1}),\,y_k-y_{k+1}\rangle
\le \frac{\alpha^2}{2\mu}\|\nabla f(x_{k+1})\|^2
+ \frac{\mu}{2}\|y_k-y_{k+1}\|^2,
\end{equation}
whose second term cancels with \eqref{eq:DEHNAG}. 

\medskip
\noindent

\textbf{Lagging of \(\nabla f(x)\).}
For the gradient cross term, arising from the lagging of $\nabla f(x)$,
the identity of squares yields
$$
\begin{aligned}
\alpha\beta\langle \nabla f(x_{k+1}),\,\nabla f(x_{k+1})-\nabla f(x_k)\rangle
&= -\frac{\alpha\beta}{2}\|\nabla f(x_k)\|^2
+ \frac{\alpha\beta}{2}\|\nabla f(x_{k+1})\|^2 \\
&\quad + \frac{\alpha\beta}{2}\|\nabla f(x_{k+1})-\nabla f(x_k)\|^2 .
\end{aligned}
$$
Combining and rearranging terms yields \eqref{eq:onestep}.
$\Box$ \end{proof}

The implicit Euler part is controlled by Lemma~\ref{lem:energy_identity}:
\begin{equation}\label{eq:IE-HNAGpp}
\begin{aligned}
&\alpha\big\langle \nabla \mathcal E(\bs z_{k+1};\hat\mu),\mathcal G(\bs z_{k+1})\big\rangle \\
\leq{}&
-c_L\alpha\mathcal E(\bs z_{k+1};\hat\mu)
-\alpha\beta\hat\mu\langle g_{k+1},x_{k+1}-x^\star\rangle
\\
&\quad
-\alpha\beta\|g_{k+1}\|^2
-\alpha\left [
d_\delta\Delta_f(x_{k+1},x^\star)
+\RV{bD_{f_{-\hat\mu}}(x_{k+1},x^\star)}
\right ].
\end{aligned}
\end{equation}
